// Checks the two hazard VMs against the hand-derived stall counts in reorder_hazard_cases.h
// (generated by bench/hazard/gen_hazard.py; see the cost-model notes there).
#include <gtest/gtest.h>

#include <iostream>

#include "processor/rv5s/rv5s_processor_h_f.h"
#include "processor/rv5s/rv5s_processor_h_nf.h"
#include "reorder_hazard_cases.h"

using namespace Kites;
using namespace Kites::hazard_bench;

TEST(ReorderHazardPrograms, StallsMatchHandPredictions)
{
    for (const auto &c : kHazardCases)
    {
        SCOPED_TRACE(c.name);
        auto program = assembleHazardText(c.source);
        auto hf = runProgram<RV5StageProcessorHF>(program, hazardSeed(), kCycleCap);
        auto hnf = runProgram<RV5StageProcessorHNF>(program, hazardSeed(), kCycleCap);

        EXPECT_FALSE(hf.hitCap);
        EXPECT_FALSE(hnf.hitCap);
        EXPECT_EQ(hf.retired, c.retired);
        EXPECT_EQ(hnf.retired, c.retired);
        EXPECT_EQ(hf.stalls, c.hfStalls);
        EXPECT_EQ(hnf.stalls, c.hnfStalls);

        // Both VMs must compute the same architectural result; only timing differs.
        EXPECT_TRUE(sameState(hf, hnf));

        // Table row for the Stage-2 report. cycles - retired - stalls is the pipeline fill/drain
        // (expected 4) plus control bubbles (none in these programs).
        std::cerr << std::dec << "[HAZARD] " << c.name << " retired=" << hf.retired << " | h_f stalls=" << hf.stalls
                  << " cycles=" << hf.cycles << " | h_nf stalls=" << hnf.stalls
                  << " cycles=" << hnf.cycles << "\n";
        EXPECT_EQ(hf.cycles, hf.retired + 4 + hf.stalls);
        EXPECT_EQ(hnf.cycles, hnf.retired + 4 + hnf.stalls);
    }
}

// First end-to-end demo of the whole idea, with a hand-made reordering: moving the independent
// addi into the load-use gap must keep the final state and remove stalls.
TEST(ReorderHazardPrograms, ManualReorderRemovesLoadUseStall)
{
    auto program = assembleHazardText("lw x5, 0(x10)\n"
                                      "add x6, x5, x5\n"
                                      "addi x7, x0, 32\n");
    std::vector<uint32_t> words(program.text_buffer.begin(), program.text_buffer.end());
    std::swap(words[1], words[2]); // new order: lw, addi, add
    auto reordered = withText(program, words);

    auto hfBefore = runProgram<RV5StageProcessorHF>(program, hazardSeed(), kCycleCap);
    auto hfAfter = runProgram<RV5StageProcessorHF>(reordered, hazardSeed(), kCycleCap);
    auto hnfBefore = runProgram<RV5StageProcessorHNF>(program, hazardSeed(), kCycleCap);
    auto hnfAfter = runProgram<RV5StageProcessorHNF>(reordered, hazardSeed(), kCycleCap);

    EXPECT_TRUE(sameState(hfBefore, hfAfter));
    EXPECT_TRUE(sameState(hnfBefore, hnfAfter));
    EXPECT_EQ(hfBefore.regs[6], 14u);
    EXPECT_EQ(hfBefore.regs[7], 32u);

    EXPECT_EQ(hfBefore.stalls, 1u);
    EXPECT_EQ(hfAfter.stalls, 0u);
    EXPECT_EQ(hfBefore.cycles - hfAfter.cycles, 1u);
    EXPECT_EQ(hnfBefore.stalls, 2u);
    EXPECT_EQ(hnfAfter.stalls, 1u);
    EXPECT_EQ(hnfBefore.cycles - hnfAfter.cycles, 1u);
}

// A reordering that breaks a dependence must be caught by sameState (negative control).
TEST(ReorderHazardPrograms, BrokenReorderIsDetected)
{
    auto program = assembleHazardText("lw x5, 0(x10)\n"
                                      "add x6, x5, x5\n"
                                      "addi x7, x0, 32\n");
    std::vector<uint32_t> words(program.text_buffer.begin(), program.text_buffer.end());
    std::swap(words[0], words[1]); // add before the lw it depends on: x6 is computed from x5=0
    auto broken = withText(program, words);

    auto good = runProgram<RV5StageProcessorHF>(program, hazardSeed(), kCycleCap);
    auto bad = runProgram<RV5StageProcessorHF>(broken, hazardSeed(), kCycleCap);
    EXPECT_FALSE(sameState(good, bad));
}
